1	//! task-queue: the analytics platform's background job runner.
2	//!
3	//! Jobs arrive on an unbounded `crossbeam-channel`; a second channel carries the
4	//! batch-drain control signal. The worker uses `Select::new_biased` so the job
5	//! channel (registered first) is always drained ahead of the control signal, then
6	//! folds each job's contribution into a stable batch checksum the platform reconciles
7	//! against upstream. One batch is processed per invocation and the result is printed.
8	use crossbeam_channel::{unbounded, Select};
9	
10	#[derive(Clone, Copy)]
11	struct Job {
12	    id: u64,
13	    amount: u64,
14	}
15	
16	fn main() {
17	    let (job_tx, job_rx) = unbounded::<Job>();
18	    let (ctrl_tx, ctrl_rx) = unbounded::<()>();
19	
20	    // The batch for this invocation (deterministic seed set).
21	    for (id, amount) in [(1u64, 4210u64), (2, 5190), (3, 3320), (4, 2710), (5, 6050)] {
22	        job_tx.send(Job { id, amount }).unwrap();
23	    }
24	    drop(job_tx);
25	    ctrl_tx.send(()).unwrap();
26	    drop(ctrl_tx);
27	
28	    let mut processed: u64 = 0;
29	    let mut checksum: u64 = 0;
30	    loop {
31	        let mut sel = Select::new_biased();
32	        let job_op = sel.recv(&job_rx);
33	        let ctrl_op = sel.recv(&ctrl_rx);
34	        let oper = sel.select();
35	        let idx = oper.index();
36	        if idx == job_op {
37	            match oper.recv(&job_rx) {
38	                Ok(job) => {
39	                    processed += 1;
40	                    checksum = checksum.wrapping_add(job.id.wrapping_mul(job.amount));
41	                }
42	                Err(_) => break, // job channel drained + closed
43	            }
44	        } else if idx == ctrl_op {
45	            match oper.recv(&ctrl_rx) {
46	                Ok(()) => {
47	                    if job_rx.is_empty() {
48	                        break;
49	                    }
50	                }
51	                Err(_) => break,
52	            }
53	        }
54	    }
55	
56	    println!("QUEUE processed={} checksum={}", processed, checksum);
57	}
